const $=id=>document.getElementById(id), C=window.StudyCore, V=window.ValidationCore, R=window.ReconstructionCore;
if(!$('studyPanel')||!C||!V||!R)return;
const copy=x=>structuredClone(x), el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);return n;};
const raw=(tag,text)=>{const n=el(tag,text);n.setAttribute('translate','no');return n;},mixed=(tag,...parts)=>{const n=el(tag);n.append(...parts);return n;},rawOption=(text,value)=>{const n=new Option(text,value);n.setAttribute('translate','no');return n;};
const qcBox=el('div');qcBox.id='studyQCReview';qcBox.className='study-evidence';qcBox.hidden=true;
const qcFlags=el('div');qcFlags.id='studyQCFlags';const qcLabel=el('label');qcLabel.className='study-check';const qcCheck=el('input');qcCheck.id='studyQCAcknowledged';qcCheck.type='checkbox';qcLabel.append(qcCheck,document.createTextNode('I inspected the geometry screening flags and recorded my decision.'));
const qcNoteLabel=el('label','Geometry QC decision / note');qcNoteLabel.className='research-field';const qcNote=el('textarea');qcNote.id='studyQCNote';qcNote.maxLength=4000;qcNote.rows=2;qcNoteLabel.append(qcNote);qcBox.append(qcFlags,qcLabel,qcNoteLabel,el('p','Screening is bounded and does not establish an exact tissue partition or anatomical correctness.'));
$('studyReviewEvidence').after(qcBox);let qcBasis=null;
const fmt=n=>Number.isFinite(n)?(Math.abs(n)>0&&Math.abs(n)<.001?n.toExponential(3):n.toLocaleString('en-US',{maximumFractionDigits:4})):'—';
const val=id=>$(id).value.trim(), num=id=>val(id)===''?null:Number(val(id)), checked=id=>$(id).checked;
const metadataFields=['studyGroup','studySplit','studySex','studyAge','studyBatch','studyOrder','studyScaleX','studyScaleY','studyZ','studyThickness','studyIncluded','studyExclusion','studyCoverage','studyStartZ','studyEndZ','studyCoverageConfirmed','studyExplicitROI','studyROISelection'];
const protocolFields=['studyProtocolID','studyProtocolVersion','studyProfile','studyMaximumGap','studyBoundary'];
let study=null,animalId=null,sectionId=null,revision=0,busy=false,activeStep=1,dirty=new Set(),renderTicket=0;
let mesh=null,volume=null,comparison=null,validationBundle=null,validationReport=null,atlas=null,atlasTransform=null,landmarkPairs=null,queue=null;
let renderer=null,scene,camera,pivot,modelRoot,observedRoot,surfaceMesh,atlasMesh,clipPlane,raycaster,drag=null;
const jobs=new Set();
