function recoveryFields(){const fields={};for(const input of $('studyPanel').querySelectorAll('input[id],select[id],textarea[id]')){if(input.type==='file'||input.id.startsWith('studyRecovery'))continue;fields[input.id]=input.type==='checkbox'?input.checked:input.multiple?[...input.selectedOptions].map(o=>o.value):input.value;}return fields;}
function recoverySnapshot(){return study?{study,fields:recoveryFields(),pending:[...dirty],selection:{animalId,sectionId,layer:layer(),step:activeStep},resources:{validationBundle,atlas,atlasTransform,landmarkPairs,queue},results:{mesh,volume,comparison,validationReport},source_originals_embedded:false}:null;}
function restoreFields(fields){const allowed=new Set([...$('studyPanel').querySelectorAll('input[id],select[id],textarea[id]')].filter(n=>n.type!=='file'&&!n.id.startsWith('studyRecovery')).map(n=>n.id));for(const[id,value]of Object.entries(fields||{})){if(!allowed.has(id)||['studyAnimal','studySection','studyLayer','studyReviewChecked'].includes(id))continue;const input=$(id);if(input.type==='checkbox'&&typeof value==='boolean')input.checked=value;else if(input.multiple&&Array.isArray(value)){for(const option of input.options)option.selected=value.includes(option.value);}else if(typeof value==='string')input.value=value;}$('studyReviewChecked').checked=false;}
async function validateRecoveryRecord(record){
 StudyRecoveryStore.validate({...record,id:record.id||crypto.randomUUID()});const next=await C.importStudy(record.study),resources=copy(record.resources||{});
 if(resources.atlas)resources.atlas=R.validateAtlas(resources.atlas);
 if(resources.landmarkPairs){if(resources.landmarkPairs.unit!=='um'||resources.landmarkPairs.direction!=='atlas_to_specimen')throw Error('Saved atlas landmarks need physical atlas-to-specimen coordinates.');const fit=R.fitRigid(resources.landmarkPairs.source,resources.landmarkPairs.target);if(resources.atlasTransform)resources.atlasTransform=fit;}else resources.atlasTransform=null;
 if(resources.validationBundle&&(resources.validationBundle.schema!=='cerebellum-validation/1'||!Array.isArray(resources.validationBundle.pairs)))throw Error('Invalid saved paired validation data.');
 if(resources.queue){if(resources.queue.schema!=='cerebellum-job-queue/1'||!Array.isArray(resources.queue.jobs)||resources.queue.jobs.length>1000)throw Error('Invalid saved queue data.');const ids=new Set();for(const job of resources.queue.jobs){if(!job||!['queued','running','needs_review','failed'].includes(job.state)||typeof job.id!=='string'||ids.has(job.id)||typeof job.animal_id!=='string'||typeof job.section_id!=='string'||!Array.isArray(job.outputs))throw Error('Invalid saved queue job.');ids.add(job.id);}}
 return {...record,study:next,resources};
}
async function openRecovery(record){await run('Checking the saved study and approval integrity…',async()=>{const prepared=await validateRecoveryRecord(record);await install(prepared.study,'Workspace restored with pending fields and approval history. Recompute derived results before using them. Original source files must still be retained separately.',null,{record:prepared});});}

function status(message,state='ready'){$('studyStatus').textContent=message;$('studyStatus').dataset.state=state;recovery?.changed();}
function currentAnimal(){return study?.animals.find(a=>a.id===animalId)||null;}
function sectionLabel(s){return s?.provenance?.original_label||s?.id||'';}
function currentSection(){return currentAnimal()?.sections.find(s=>s.id===sectionId)||null;}
function layer(){return $('studyLayer').value;}
function clean(){if(dirty.size)throw Error('Apply or discard unapplied metadata and protocol fields first.');if(!study)throw Error('Open a study first.');}
function download(name,object,type='application/json'){const data=typeof object==='string'?object:JSON.stringify(object,null,2),url=URL.createObjectURL(new Blob([data],{type})),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);status('Download requested. Check the downloaded file before relying on it. Browser recovery is retained.');}
function evidence(id,lines){$(id).replaceChildren(...lines.filter(Boolean).map(s=>s instanceof Node?s:el('p',s)));}
function table(id,headers,rows){const t=el('table'),head=el('thead'),tr=el('tr');headers.forEach(h=>tr.append(el('th',h)));head.append(tr);const body=el('tbody');rows.forEach(row=>{const r=el('tr');row.cells.forEach(c=>{const td=el('td');c instanceof Node?td.append(c):td.textContent=String(c??'—');r.append(td);});if(row.select){r.dataset.section=row.select[1];r.dataset.selected=String(row.select[0]===animalId&&row.select[1]===sectionId);r.tabIndex=0;r.setAttribute('aria-label','Select '+row.select.join(' / '));const select=()=>selectSection(...row.select);r.addEventListener('click',select);r.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}});}body.append(r);});t.append(head,body);$(id).replaceChildren(t);}
function controls(){const exists=!!study,usable=exists&&!busy&&!dirty.size,s=!!currentSection();metadataFields.concat(protocolFields).forEach(id=>$(id).disabled=!exists||busy);$('studyROISelection').disabled=!exists||busy||!checked('studyExplicitROI');['studyAnimal','studySection'].forEach(id=>$(id).disabled=!exists||busy);$('studyLayer').disabled=busy||dirty.size>0;$('studyStructure').disabled=!exists||busy||dirty.size>0;
 ['studyImport','studyFromAnalysis','studyExample','studyResearchAnimalID'].forEach(id=>$(id).disabled=busy);$('studyFromResearch').disabled=busy||!val('studyResearchAnimalID');$('studyAddResearch').disabled=!usable||!val('studyResearchAnimalID');$('studyAddAnalysis').disabled=!usable||!currentAnimal();$('studyDiscard').disabled=!dirty.size||busy;$('studyApplyMetadata').disabled=!exists||busy||!dirty.has('metadata');$('studyApplyProtocol').disabled=!exists||busy||!dirty.has('protocol');
 ['studySave','studyManifest'].forEach(id=>$(id).disabled=!usable);['studyReconstruct','studyVolume'].forEach(id=>$(id).disabled=!usable||!currentAnimal());$('studyVolume').disabled=!usable||!currentAnimal()||!!val('studyStructure');$('studyCompare').disabled=!usable;$('studyApprove').disabled=!usable||!s||!checked('studyReviewChecked')||!val('studyReviewer')||!val('studyReviewProtocol')||(!qcBox.hidden&&(!checked('studyQCAcknowledged')||!val('studyQCNote')));
 ['studyReviewer','studyReviewProtocol','studyReviewChecked','studyReviewScope','studyQCAcknowledged','studyQCNote'].forEach(id=>$(id).disabled=!exists||busy);$('studyMeshSave').disabled=$('studyContoursCSV').disabled=!mesh||!usable;$('studySurfaceOBJ').disabled=!mesh?.indices?.length||!usable;$('studyComparisonSave').disabled=$('studyComparisonCSV').disabled=!comparison||!usable;
 $('studyValidationRun').disabled=!validationBundle||busy||dirty.size>0;$('studyValidationSave').disabled=!validationReport||busy||dirty.size>0;$('studyValidationImport').disabled=busy||dirty.size>0;$('studyValidationGrid').disabled=busy;
 $('studyAtlasFit').disabled=!atlas||!landmarkPairs||busy;$('studyAtlasSave').disabled=!atlasTransform||busy;$('studyQueueSave').disabled=!queue||busy;
 ['studyAtlasImport','studyAtlasPairs','studyQueueImport','studyAllowGaps','studyMeshGrid'].forEach(id=>$(id).disabled=busy);$('studyCancel').disabled=!busy;recovery?.controls();
}
function markDirty(kind){dirty.add(kind);$('studyReviewChecked').checked=false;controls();status('Unapplied '+[...dirty].join(' and ')+' fields. Apply or discard before reviewing, computing or exporting.','pending');}
function stop(message){revision++;for(const job of jobs){job.worker.terminate();clearTimeout(job.timer);job.reject(Error('Computation stopped.'));if(job.url)URL.revokeObjectURL(job.url);}jobs.clear();busy=false;controls();if(message)status(message);}
function clearDerived(){stop();mesh=volume=comparison=validationReport=null;['studyMeshEvidence','studyVolumeResults','studyComparisonSummary','studyComparisonChart','studyComparisonTable','studyValidationResults'].forEach(id=>$(id).replaceChildren());drawModel();}
function clearAlignment(){atlasTransform=null;landmarkPairs=null;atlasEvidence();}
function showStep(n){activeStep=n;for(let i=1;i<=6;i++){const b=$('studyTab'+i);b.setAttribute('aria-selected',String(i===n));b.tabIndex=i===n?0:-1;$('studyPage'+i).classList.toggle('hidden',i!==n);}if(n===4)requestAnimationFrame(resize);showReadiness();recovery?.changed();}
function showReadiness(){const stage=readiness?.stages.find(s=>s.number===activeStep);if(!stage){$('studyWorkflowState').replaceChildren();return;}const labels={ready:'Inputs ready',partial:'Inputs incomplete',blocked:'Missing inputs',completed_for_current_input:'Completed for current inputs',blocked_for_current_input:'Blocked for current inputs',not_run_for_current_input:'Not run for current inputs',report_recomputed:'Validation report recomputed',review_completed_for_current_input:'Review completed for current inputs',not_established:'Not established',measured_against_declared_criteria_only:'Measured against declared criteria only'};const values=[['Input readiness',stage.input_status||stage.status],['Computation',stage.execution_status||'not_run_for_current_input'],['Scientific evidence',stage.scientific_status||'not_established']];$('studyWorkflowState').replaceChildren(...values.map(([name,value])=>{const row=el('div');row.append(el('strong',name),el('span',labels[value]||value.replaceAll('_',' ')));return row;}));const details=el('details'),summary=el('summary','Completion criteria');details.append(summary);for(const criterion of stage.criteria||[]){const row=el('p');row.append(el('strong',criterion.met?'Met':'Missing'),document.createTextNode(' · '),el('span',criterion.detail));details.append(row);}for(const reason of stage.reasons||[])details.append(el('p',reason));$('studyWorkflowState').append(details);$('studyWorkflowState').dataset.execution=stage.execution_status||'';$('studyWorkflowState').dataset.science=stage.scientific_status||'';}
async function run(message,task){if(busy)return;busy=true;const token=revision;controls();status(message,'pending');try{const result=await task(()=>token===revision);if(token===revision)controls();return result;}catch(e){if(token===revision)status(e.message,'error');return false;}finally{if(token===revision){busy=false;controls();await render();recovery?.changed();}}}
function workerTask(kind,payload){return new Promise((resolve,reject)=>{let url=null,worker;if(kind==='native'){const sources=['analysis_core.js','study_core.js'].map(f=>new URL('./assets/'+f,location.href).href);url=URL.createObjectURL(new Blob(['importScripts('+sources.map(x=>JSON.stringify(x)).join(',')+');onmessage=async({data})=>{try{const result=await StudyCore[data.operation](data.study,...data.args);postMessage({result});}catch(e){postMessage({error:e.message});}}'],{type:'text/javascript'}));worker=new Worker(url);}else worker=new Worker('./assets/'+kind+'_worker.js');const job={worker,url,reject,timer:null};const finish=(error,result)=>{if(!jobs.has(job))return;jobs.delete(job);worker.terminate();clearTimeout(job.timer);if(url)URL.revokeObjectURL(url);error?reject(Error(error)):resolve(result);};job.timer=setTimeout(()=>finish('Computation exceeded two minutes; reduce the grid or dataset.'),120000);jobs.add(job);worker.onerror=e=>finish(e.message||'Worker failed.');worker.onmessage=({data})=>finish(data.error,data.result);worker.postMessage({...payload,id:revision,request_id:revision});});}
async function fileJSON(input,max=96*1024*1024){const file=input.files?.[0];if(!file)throw Error('No file selected.');if(file.size>max)throw Error('JSON exceeds the '+Math.round(max/1024/1024)+' MiB import bound.');return JSON.parse(await file.text());}
function field(id,value){$(id).value=value??'';}
function structureChoice(){const selected=val('studyStructure');return selected.startsWith('cortex:')?{corticalRegion:selected.slice(7)}:selected.startsWith('roi:')?{roiName:selected.slice(4)}:{};}
function syncStructureOptions(){const selected=val('studyStructure'),sections=currentAnimal()?.sections.filter(s=>s.included)||[],rois=sections.flatMap(s=>s.rois.filter(r=>r.included!==false)),names=[...new Set(rois.filter(r=>!(typeof r.metadata?.model_class==='string'&&r.metadata.model_class.startsWith('LOBULE_'))).map(r=>r.name))].sort(),regions=[...new Set(rois.filter(r=>r.kind==='area'&&r.region&&r.metadata?.model_class==='LOBULE_'+r.region&&r.metadata?.anatomy_scope==='ML+GL annotated cortical subregions; not whole lobule').map(r=>r.region))].sort(),named=el('optgroup'),cortical=el('optgroup');named.label='Named ROIs';cortical.label='Annotated cortical regions';named.append(...names.map(name=>rawOption(name,'roi:'+name)));cortical.append(...regions.map(region=>rawOption(region,'cortex:'+region)));$('studyStructure').replaceChildren(el('option','Selected analysis layer'),...(regions.length?[cortical]:[]),...(names.length?[named]:[]));$('studyStructure').options[0].value='';$('studyStructure').value=[...$('studyStructure').options].some(option=>option.value===selected)?selected:'';}

function syncForms(){syncStructureOptions();const a=currentAnimal(),s=currentSection();$('studyAnimal').replaceChildren(...(study?.animals||[]).map(a=>rawOption(a.id+' · '+a.group,a.id)));$('studyAnimal').value=animalId||'';$('studySection').replaceChildren(...(a?.sections||[]).map(s=>rawOption(sectionLabel(s)+(s.included?'':' · excluded'),s.id)));$('studySection').value=sectionId||'';
 if(a&&s){const values={studyGroup:a.group,studySplit:a.split,studySex:a.sex,studyAge:a.age_days,studyBatch:a.batch,studyOrder:s.order,studyScaleX:s.calibration.um_per_pixel_x,studyScaleY:s.calibration.um_per_pixel_y,studyZ:s.z_um,studyThickness:s.thickness_um,studyExclusion:s.exclusion_reason,studyCoverage:a.coverage.kind,studyStartZ:a.coverage.start_um,studyEndZ:a.coverage.end_um};Object.entries(values).forEach(([id,v])=>field(id,v));$('studyIncluded').checked=s.included;$('studyCoverageConfirmed').checked=a.coverage.confirmed;$('studyExplicitROI').checked=Object.hasOwn(s.layer_selection,layer());$('studyROISelection').replaceChildren(...s.rois.filter(r=>r.kind==='area').map(r=>{const o=rawOption(r.name,r.name);o.selected=(s.layer_selection[layer()]||[]).includes(r.name);return o;}));}
 if(study){const p=study.protocol;Object.entries({studyProtocolID:p.id,studyProtocolVersion:p.version,studyProfile:p.measurement_profile,studyMaximumGap:p.maximum_gap_um,studyBoundary:p.boundary_definition}).forEach(([id,v])=>field(id,v));}
 $('studyReviewChecked').checked=false;$('studyReviewScope').value='source_linked';controls();
}
async function render(){const ticket=++renderTicket,document=study;if(!document){$('studyBadge').textContent='No study loaded';return;}const states=new Map();for(const a of document.animals)for(const s of a.sections)states.set(a.id+'\0'+s.id,await C.reviewStatus(document,a.id,s.id));const ready=await C.stageReadiness(document,{layer:layer(),allowExcludedGapInterpolation:checked('studyAllowGaps'),volumeResult:volume,comparisonResult:comparison,validationReport});if(ticket!==renderTicket||study!==document)return;
 readiness=ready;showReadiness();if(validationBundle&&!validationReport){const binding=V.studyBinding(validationBundle,document);if(!binding.current_input_match)evidence('studyValidationResults',['Saved validation inputs are retained as historical evidence. Rematch current predictions and the complete protocol for current-study validation.',...binding.issues]);}const synthetic=document.synthetic===true;$('studyBadge').textContent=(synthetic?'Synthetic · ':'')+ready.counts.animals+' animals · '+ready.counts.sections+' sections';$('studyBadge').dataset.kind=synthetic?'synthetic':'study';$('studyScope').textContent=synthetic?'Synthetic example — interface and calculation checks only. These shapes are not animal anatomy.':'No trained Nissl model is bundled. Source files stay unchanged. Save the study and retain the original image / ROI / CSV files.';
 ready.stages.forEach(stage=>{const b=$('studyTab'+stage.number);b.dataset.state=stage.status;b.querySelector('small').textContent=stage.status==='ready'?'Inputs ready':stage.status==='partial'?'Inputs incomplete':'Missing inputs';b.title=stage.title;});
 $('studyReadinessNote').textContent=ready.counts.approved_sections+' / '+ready.counts.included_sections+' included sections approved. Readiness is not biological validation.';
 const rows=document.animals.flatMap(a=>a.sections.map(s=>({cells:[raw('span',a.id),raw('span',a.group),raw('span',sectionLabel(s)),fmt(s.z_um),s.included?'Included':raw('span',s.exclusion_reason),states.get(a.id+'\0'+s.id)],select:[a.id,s.id]})));table('studyInventory',['Animal','Group','Section','Z · µm','Inclusion','Review'],rows);table('studyReviewQueue',['Animal','Group','Section','Z · µm','Inclusion','Review'],rows);
 const s=currentSection();if(s){const digest=await C.sectionFingerprint(document,animalId,sectionId);if(ticket!==renderTicket)return;const qc=C.sectionQCStatus(s);qcBox.hidden=!qc.flags.length;qcFlags.replaceChildren(...qc.flags.map(flag=>mixed('p',el('span',flag.message),...(flag.roi_ids?.length?[window.document.createTextNode(' · '),raw('span',flag.roi_ids.join(' / '))]:[]))));if(qcBasis!==digest){qcBasis=digest;qcCheck.checked=false;qcNote.value='';}evidence('studyReviewEvidence',[mixed('p',raw('span',animalId),' / ',raw('span',sectionLabel(s)),...(sectionLabel(s)!==s.id?[' · ID ',raw('span',s.id)]:[]),' · '+states.get(animalId+'\0'+s.id)+' · '+s.origin+' observations'),s.source?mixed('p','Source: ',raw('span',s.source.name),' · '+s.source.width+' × '+s.source.height+' px · SHA-256 '+s.source.sha256):'Original image identity is missing. Verify the original source before approving.',s.rois.length+' ROIs · XY '+fmt(s.calibration.um_per_pixel_x)+' × '+fmt(s.calibration.um_per_pixel_y)+' µm/px · Z '+fmt(s.z_um)+' µm',s.included?'Section included.':mixed('p','Excluded: ',raw('span',s.exclusion_reason)),'Current evidence SHA-256: '+digest,s.review?mixed('p','Reviewed by ',raw('span',s.review.reviewer),' · '+s.review.at+' · ',raw('span',s.review.protocol)):null]);}
 try{const split=V.checkSplits(document);evidence('studySplitFindings',['Split provenance: '+split.status.replaceAll('_',' '),...split.issues.map(i=>i.message)]);}catch(e){evidence('studySplitFindings',[e.message]);}controls();window.document.dispatchEvent(new Event('cerebellum-study-change'));
}
async function applyStudyWorkspace(candidate){clearDerived();study=candidate.study;animalId=candidate.selection?.animalId||study.animals[0]?.id||null;if(!currentAnimal())animalId=study.animals[0]?.id||null;sectionId=candidate.selection?.sectionId||currentAnimal()?.sections[0]?.id||null;if(!currentSection())sectionId=currentAnimal()?.sections[0]?.id||null;if(['CB','ML','GL','WM'].includes(candidate.selection?.layer))$('studyLayer').value=candidate.selection.layer;dirty=new Set(candidate.pending||[]);const data=candidate.resources||{};validationBundle=data.validationBundle||null;atlas=data.atlas||null;atlasTransform=data.atlasTransform||null;landmarkPairs=data.landmarkPairs||null;queue=data.queue||null;syncForms();restoreFields(candidate.fields);atlasEvidence();$('studyQueueSummary').replaceChildren();$('studyQueueTable').replaceChildren();queueDisplay();showStep(Math.min(6,Math.max(1,Number(candidate.selection?.step)||1)));await render();}
async function install(next,message,preferredAnimalId=null,{record=null,add=false,resources=null}={}){
 const candidate=record?{...record,study:next}:{study:next,fields:{},pending:[],selection:{animalId:preferredAnimalId||next.animals[0]?.id||null,sectionId:null,layer:layer(),step:1},resources:resources||{},results:{},source_originals_embedded:false};
 const apply=()=>applyStudyWorkspace(candidate);
 const installed=await recovery.replace(candidate,apply,{ask:!add});if(installed)status(message);else status('Workspace switch cancelled. The current study and pending fields are unchanged.');return installed;
}
function selectSection(a,s){if(dirty.size){$('studyAnimal').value=animalId;$('studySection').value=sectionId;status('Apply or discard unapplied fields before selecting another section.','pending');return;}if(a!==animalId){clearDerived();clearAlignment();}animalId=a;sectionId=s;syncForms();render();drawModel();recovery?.changed();}
function changedFields(target,patch){return Object.fromEntries(Object.entries(patch).filter(([key,value])=>JSON.stringify(target[key])!==JSON.stringify(value)));}
function applyMetadata(){try{if(!study)return;const a=currentAnimal(),s=currentSection();const ap=changedFields(a,{group:val('studyGroup'),split:val('studySplit'),sex:val('studySex')||null,age_days:num('studyAge'),batch:val('studyBatch')||null,coverage:{kind:val('studyCoverage'),start_um:num('studyStartZ'),end_um:num('studyEndZ'),confirmed:checked('studyCoverageConfirmed')}}),selection={...s.layer_selection};if(checked('studyExplicitROI'))selection[layer()]=[...$('studyROISelection').selectedOptions].map(o=>o.value);else delete selection[layer()];const sp=changedFields(s,{order:num('studyOrder'),z_um:num('studyZ'),thickness_um:num('studyThickness'),calibration:{um_per_pixel_x:num('studyScaleX'),um_per_pixel_y:num('studyScaleY')},included:checked('studyIncluded'),exclusion_reason:checked('studyIncluded')?'':val('studyExclusion'),layer_selection:selection});let next=study;if(Object.keys(ap).length)next=C.patchAnimal(next,a.id,ap);if(Object.keys(sp).length)next=C.patchSection(next,a.id,s.id,sp);clearDerived();study=next;clearAlignment();dirty.delete('metadata');if(!dirty.size)syncForms();else controls();render();status('Metadata applied. Affected approvals were cleared; original ROI coordinates and source records are retained.');}catch(e){status(e.message,'error');}}
